// Récupère les données, qu'elles soient dans 'body' ou à la racine
const inputData = $input.item.json;
const data = inputData.body || inputData; 

// Récupère les variables proprement
const chatInput = data.chatInput || "Bonjour";
const sessionId = data.sessionId || `session-${Date.now()}`;
const authToken = data.authToken;

// Renvoie un JSON propre et plat pour l'Agent IA
return {
  json: {
    chatInput: chatInput,  // Pour ton expression actuelle
    input: chatInput,      // Sécurité pour l'Agent
    sessionId: sessionId,
    authToken: authToken
  }
};
